fn solve(n: i8, k: i8) -> i8 {
    // Compute the nonnegative remainder of n divided by k.
    // Since n >= 0 and k > 0, n.rem_euclid(k) == n % k, but rem_euclid is explicit.
    let r = n.rem_euclid(k);
    // Distance by going "up" to the next multiple of k
    let k_minus_r = k - r;
    // Return whichever is smaller: going down by r or up by (k - r)
    if r < k_minus_r {
        r
    } else {
        k_minus_r
    }
}

