    #[test]
    fn test_distance_down() {
        assert_eq!(solve(5, 3), 1);  // 5 ≡ 2 mod 3, min(2,1)=1
        assert_eq!(solve(7, 5), 2);  // 7 ≡ 2 mod 5, min(2,3)=2
    }

    #[test]
